    [.33,.073],[.314,.077],[.307,.061],[.341,-.052],[.361,-.244],[.354,-.411],[.311,-.525],[.25,-.565],[0,-.565]];
  return new THREE.LatheGeometry(points.map(([x,y])=>new THREE.Vector2(x,y)),64);
